import { useEffect, useState } from "react";
import { db } from "../js/firebaseConfig";
import { collection, addDoc, serverTimestamp, query, onSnapshot } from "firebase/firestore";

export default function CreateGroup({ currentUser, setScreen }) {
    const [name, setName] = useState("");
    const [users, setUsers] = useState([]);
    const [selected, setSelected] = useState([]);

    useEffect(() => {
        const q = query(collection(db, "users"));
        onSnapshot(q, s => {
            setUsers(s.docs.map(d => ({ id: d.id, ...d.data() })));
        });
    }, []);

    const toggle = (id) => {
        setSelected(prev => 
            prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
        );
    };

    const create = async () => {
        if (!name || selected.length === 0) return alert("Preencha tudo.");

        const docRef = await addDoc(collection(db, "groups"), {
            name,
            members: [currentUser.uid, ...selected],
            createdAt: serverTimestamp()
        });

        setScreen("contacts");
    };

    return (
        <div>
            <h2>Criar Grupo</h2>

            <input placeholder="Nome do grupo" value={name} onChange={e => setName(e.target.value)} />

            <h3>Membros</h3>
            {users.filter(u => u.id !== currentUser.uid).map(u => (
                <label key={u.id}>
                    <input type="checkbox" checked={selected.includes(u.id)} onChange={() => toggle(u.id)} />
                    {u.email}
                </label>
            ))}

            <button onClick={create}>Criar</button>
            <button onClick={() => setScreen("contacts")}>Cancelar</button>
        </div>
    );
}
